    id, user_id, task_type, story_theme, product_info, target_platform, target_audience,
    story_style, story_duration, current_node, status, failure_reason, debug_prompts,
    model_provider, model_name, model_params, created_at, updated_at
) values (
    cast(#{id} as uuid), #{userId}, #{taskType}, #{storyTheme}, #{productInfo}, #{targetPlatform},
